        assert_eq!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);
        let restored=Generation3dSnapshotRead::new(Generation3dSnapshot::from_sqlite_database(&expected,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap());assert_eq!(project(&restored),expected);
        let short=SqliteDatabaseLimits{max_value_bytes:maximum-1,..SqliteDatabaseLimits::default()};
        assert!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());
        match Generation3dSnapshot::from_sqlite_database(&expected,&mut SqliteSnapshotControl::new(&mut |_|true,short)){Err(_)=>{},Ok(owner)=>{let _held=Generation3dSnapshotRead::new(owner);panic!("short semantic reconstruction accepted");}}
        for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text] {
            let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<Generation3dSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<Generation3dSnapshot as store::ArtifactDsl>::print_dsl(&source))};
            assert_eq!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),payload);
            let actual=Generation3dSnapshotRead::new(Generation3dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap());assert_eq!(project(&actual),expected);
            assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err(),"{} short semantic native encode",case["name"]);
            match Generation3dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,short)){Err(_)=>{},Ok(owner)=>{let _held=Generation3dSnapshotRead::new(owner);panic!("short semantic native decode accepted");}}
        }
        eprintln!("[DEBUG] Generation3d complete independent SQL cell semantic boundary case={} bytes={} rows=122 tables=36 both_native=true",case["name"],maximum);
    }
}

